def optimal(roster):
    by = {}
    for n, p, v, s in roster: by.setdefault(p, []).append((v, n))
    for p in by: by[p].sort(reverse=True)
    take = lambda p, k: by.get(p, [])[:k]
    qb, k, d = take('QB', 1), take('K', 1), take('DST', 1)
    rb, wr, te = take('RB', 2), take('WR', 2), take('TE', 1)
    used = {n for _, n in rb + wr + te}
    flex = sorted([x for p in ('RB', 'WR', 'TE') for x in by.get(p, []) if x[1] not in used], reverse=True)[:1]
    lineup = qb + rb + wr + te + flex + k + d
    return round(sum(v for v, _ in lineup), 1), lineup
def actual(r): return round(sum(v for n, p, v, s in r if s), 1)
def bench(r): return round(sum(v for n, p, v, s in r if not s), 1)
